<script setup lang="ts">
import {computed,ref,onMounted} from 'vue'
import {Plus,Pencil,X,ArrowUp,ArrowDown,FlaskConical,Check} from 'lucide-vue-next'
import DataList from './DataList.vue'
import {boot,api,refresh,localDate} from '../data'
import type {Rule,Stage,Inputs,Quote,Product} from '../types'
const props=defineProps<{month:string;weightsOnly?:boolean}>()
const activeFilter=ref(''),catalogList=ref<any>(null),tick=ref(0)
const tab=ref(props.weightsOnly?'grossWeights':'workers'),error=ref(''),success=ref(''),busy=ref(false),users=ref<any[]>([]),form=ref<any>(null),ruleProduct=ref<Product|null>(null)
const rows=computed<any[]>(()=>tab.value==='workers'?boot.value?.workers||[]:tab.value==='categories'?boot.value?.categories||[]:tab.value==='products'?boot.value?.products||[]:tab.value==='groups'?boot.value?.groups||[]:tab.value==='baskets'?boot.value?.baskets||[]:tab.value==='plots'?boot.value?.plots||[]:tab.value==='grossWeights'?boot.value?.grossWeights||[]:users.value)
async function loadUsers(){users.value=await api('/users')}
onMounted(()=>{if(!props.weightsOnly)loadUsers().catch(e=>error.value=e.message)})
function edit(row?:any){form.value={name:'',code:'',phone:'',categoryId:'',username:'',role:'RECORDER',password:'',groupId:'',weightKg:'',active:true,...row,...(row?.group_id?{groupId:row.group_id}:{}),...(row?.weight_kg?{weightKg:row.weight_kg}:{}),...(row?.display_name?{name:row.display_name}:{}),...(row?.category_id?{categoryId:row.category_id}:{})};error.value=''}
async function save(){busy.value=true;error.value='';try{await api('/catalog/'+tab.value,{method:'POST',body:JSON.stringify(form.value)});await refresh(props.month);if(!props.weightsOnly)await loadUsers();if(catalogList.value)catalogList.value.query=form.value.name;tick.value++;form.value=null;success.value='资料已保存'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const scope=ref('MONTH');
const rule=ref<Rule>({mode:'SEGMENTS',stages:[]}),effective=ref(localDate().slice(0,7)+'-01'),reason=ref(''),trialInput=ref<Inputs>({quantities:{},totalWeight:null,weightUnit:'kg'}),quote=ref<Quote|null>(null)
function configure(p:Product){ruleProduct.value=p;const existing=boot.value?.rules.filter(r=>r.product_id===p.id).sort((a,b)=>b.effective_date.localeCompare(a.effective_date)||b.revision-a.revision)[0];rule.value=existing?JSON.parse(existing.rule_json):{mode:'SEGMENTS',stages:[]};if(!rule.value.stages.length)addStage();quote.value=null;error.value='';reason.value='';trialInput.value={quantities:{},totalWeight:null,weightUnit:'kg'}}
function addStage(){rule.value.stages.push({key:'stage_'+crypto.randomUUID().slice(0,8),label:'采摘计件',type:'PIECE',rate:'3',kgPerPiece:null,limit:null,min:null,max:null})}
function move(index:number,offset:number){const list=rule.value.stages;[list[index],list[index+offset]]=[list[index+offset],list[index]];quote.value=null}
function payload(){return {mode:rule.value.mode,stages:rule.value.stages.map(s=>Object.fromEntries(Object.entries(s).map(([k,v])=>[k,v===''?null:v])))}}
async function trial(){error.value='';quote.value=null;try{quote.value=await api('/rules/trial',{method:'POST',body:JSON.stringify({rule:payload(),inputs:trialInput.value})})}catch(e){error.value=(e as Error).message}}
async function publish(){error.value='';if(!reason.value.trim()){error.value='请填写调整原因';return}busy.value=true;try{await api('/rules',{method:'POST',body:JSON.stringify({productId:ruleProduct.value?.id,effectiveDate:effective.value,rule:payload(),reason:reason.value,scope:scope.value})});await refresh(props.month);ruleProduct.value=null;success.value='产品计费规则已保存，应发与未付按适用日期重新核算，历史快照保留'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function invalidate(){quote.value=null}
</script>
<template><div class="page-intro"><div><p class="eyebrow">把基础资料准备好</p><h1>{{weightsOnly?'重量配置':'基础资料'}}</h1><p class="muted">类别负责归类，具体产品分别配置计费规则。</p></div><button class="primary" @click="edit()"><Plus :size="18"/>新增{{tab==='workers'?'工人':tab==='categories'?'类别':tab==='products'?'产品':tab==='groups'?'班组':tab==='baskets'?'筐型':tab==='plots'?'地块':tab==='grossWeights'?'毛重配置':'账号'}}</button></div>
  <p v-if="success" class="notice success" role="status">{{success}}</p><p v-if="error&&!form&&!ruleProduct" class="notice danger">{{error}}</p>
  <div class="tabs"><button v-for="t in [{key:'workers',name:'工人'},{key:'groups',name:'班组'},{key:'plots',name:'地块 / 大棚'},{key:'baskets',name:'筐型与皮重'},{key:'grossWeights',name:'毛重配置'},{key:'categories',name:'产品类别'},{key:'products',name:'产品与计费'},{key:'users',name:'系统账号'}].filter(t=>!weightsOnly||['baskets','grossWeights'].includes(t.key))" :key="t.key" :class="{active:tab===t.key}" @click="tab=t.key">{{t.name}}</button></div>
  <DataList ref="catalogList" :endpoint="'/query/catalog/'+tab" :params="{active:activeFilter}" :refresh-key="tick" :rows="rows" scope="基础资料" @reset="activeFilter=''"><template #filters><label>使用状态<select v-model="activeFilter" aria-label="资料使用状态"><option value="">全部</option><option value="true">使用中</option><option value="false">已停用</option></select></label></template><template #default="{items}"><div class="panel table-wrap"><table><thead><tr><th>{{tab==='workers'?'工号':tab==='users'?'账号':'名称'}}</th><th>{{tab==='products'?'所属类别':'详细信息'}}</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in items" :key="r.id"><td><strong>{{tab==='workers'?r.code:tab==='users'?r.username:r.name}}</strong></td><td>{{tab==='workers'?r.name+' · '+(boot?.groups?.find(g=>g.id===r.group_id)?.name||'未分组')+' · '+(r.phone||'未填电话'):tab==='users'?r.display_name+' · '+(r.role==='ADMIN'?'老板':'记录员'):tab==='products'?boot?.categories.find(c=>c.id===r.category_id)?.name:tab==='grossWeights'?r.weight_kg+' 公斤':tab==='baskets'?r.weight_kg+' 公斤/个':tab==='groups'?'用于录入、查询和核对表筛选':tab==='plots'?'用于实际数量归属与人工成本统计':'仅用于归类管理'}}</td><td><span class="tag" :class="r.active?'good':'neutral'">{{r.active?'使用中':'已停用'}}</span></td><td><div class="button-row"><button class="compact" @click="edit(r)"><Pencil :size="14"/>编辑</button><button v-if="tab==='products'" class="compact" @click="configure(r)">配置计费规则</button></div></td></tr></tbody></table><div v-if="!rows.length" class="empty">暂无资料，点击右上角新增。</div></div></template></DataList>
  <div v-if="form" class="modal-shade" @click.self="form=null"><section class="modal" role="dialog" aria-modal="true" aria-label="编辑基础资料"><div class="modal-head"><h2>{{form.id?'编辑资料':'新增资料'}}</h2><button class="icon-button" aria-label="关闭" @click="form=null"><X/></button></div><form @submit.prevent="save"><label>{{tab==='users'?'显示姓名':'名称'}}<input v-model="form.name" maxlength="80" required/></label><template v-if="tab==='workers'"><label>工号<input v-model="form.code" maxlength="40" required/></label><label>联系方式<input v-model="form.phone" maxlength="40"/></label><label>默认班组<select v-model="form.groupId"><option value="">未分组</option><option v-for="g in boot?.groups?.filter(g=>g.active||g.id===form.groupId)" :key="g.id" :value="g.id">{{g.name}}</option></select></label><p class="muted">默认班组用于筛选人员。实际录入时可选其他班组，修改资料不会改变历史数量归属。</p></template><label v-if="tab==='baskets'||tab==='grossWeights'">{{tab==='baskets'?'单筐皮重（公斤）':'毛重（公斤）'}}<input v-model="form.weightKg" type="number" min="0.000001" step="any" required/></label><label v-if="tab==='products'">所属类别<select v-model="form.categoryId" required><option value="" disabled>选择类别</option><option v-for="c in boot?.categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><template v-if="tab==='users'"><label>登录账号<input v-model="form.username" required pattern="[a-zA-Z0-9_-]{3,40}"/></label><label>{{form.id?'新密码（留空不修改）':'初始密码'}}<input v-model="form.password" type="password" minlength="8" maxlength="72" :required="!form.id" autocomplete="new-password"/></label><label>角色<select v-model="form.role"><option value="RECORDER">记录员</option><option value="ADMIN">老板</option></select></label></template><label class="check-label"><input v-model="form.active" type="checkbox"/>启用</label><p v-if="error" class="notice danger">{{error}}</p><div class="modal-actions"><button type="button" @click="form=null">取消</button><button class="primary" :disabled="busy">保存资料</button></div></form></section></div>
  <div v-if="ruleProduct" class="modal-shade"><section class="modal rule-modal" role="dialog" aria-modal="true" aria-label="配置计费规则"><div class="modal-head"><div><p class="eyebrow">{{ruleProduct.name}} · 独立计费规则</p><h2>配置并保存计费规则</h2></div><button class="icon-button" aria-label="关闭" @click="ruleProduct=null"><X/></button></div>
    <div @input="invalidate" @change="invalidate"><div class="form-grid"><label>适用范围<select v-model="scope"><option value="MONTH">指定月份（整月追溯调整）</option><option value="FROM_DATE">自指定日期起（新规则 / 降价）</option></select></label><label>生效日期<input v-model="effective" type="date" required/></label><label>工作量分配方式<select v-model="rule.mode"><option value="SEGMENTS">分段填写各部分数量</option><option value="ALLOCATE">按总重量和规则顺序分配</option></select></label></div><p class="notice">{{rule.mode==='SEGMENTS'?'记录员按各阶段填写互不重叠的工作量。阶段顺序和条件由老板设置。':'记录员填写总重量；阶段按下列顺序从剩余重量取量。计件需设置每筐标准公斤数，可设阶段上限。剩余重量未分配完时不允许保存。'}}</p>
    <article v-for="(s,i) in rule.stages" :key="s.key" class="stage-card"><div class="section-title"><h3>优先级 {{i+1}}</h3><div class="button-row"><button class="icon-button" :disabled="i===0" aria-label="上移" @click="move(i,-1)"><ArrowUp :size="16"/></button><button class="icon-button" :disabled="i===rule.stages.length-1" aria-label="下移" @click="move(i,1)"><ArrowDown :size="16"/></button><button class="text-danger" :disabled="rule.stages.length===1" @click="rule.stages.splice(i,1);invalidate()">移除</button></div></div><div class="form-grid"><label>阶段名称<input v-model="s.label" maxlength="60"/></label><label>计费方式<select v-model="s.type"><option value="PIECE">计件 · 筐（步长 0.5）</option><option value="WEIGHT">计重 · 公斤</option></select></label><label>单价（元/{{s.type==='PIECE'?'筐':'公斤'}}）<input v-model="s.rate" type="number" min="0" step="0.0001"/></label><label v-if="rule.mode==='ALLOCATE'&&s.type==='PIECE'">每筐标准重量（公斤）<input v-model="s.kgPerPiece" type="number" min="0.000001" step="any"/></label><label>本阶段数量上限（可留空）<input v-model="s.limit" type="number" min="0" :step="s.type==='PIECE'?0.5:'any'"/></label><label>适用数量下限（可留空）<input v-model="s.min" type="number" min="0" step="any"/></label><label>适用数量上限（可留空）<input v-model="s.max" type="number" min="0" step="any"/></label></div></article><button :disabled="rule.stages.length>=6" @click="addStage();invalidate()"><Plus :size="16"/>增加计费阶段</button><label>调整原因<input v-model="reason" maxlength="500" placeholder="例如：本月番茄计件单价上调" required/></label><p class="muted">追溯涨价请选择目标月份第一天；降价请选择实际生效日期。历史快照保留，更改后应发与未付按最新核算更新。试算可选，保存时校验。</p></div>
    <section class="trial-panel"><h3><FlaskConical :size="18"/>用示例数据试算</h3><div class="form-grid"><label v-if="rule.mode==='ALLOCATE'">总重量<input v-model="trialInput.totalWeight" type="number" min="0" step="any" @input="invalidate"/></label><template v-else><label v-for="s in rule.stages" :key="s.key">{{s.label}}（{{s.type==='PIECE'?'筐':'所选重量单位'}}）<input v-model="trialInput.quantities[s.key]" type="number" min="0" :step="s.type==='PIECE'?0.5:'any'" @input="invalidate"/></label></template><label>重量单位<select v-model="trialInput.weightUnit" @change="invalidate"><option value="kg">公斤</option><option value="jin">斤</option><option value="g">克</option></select></label></div><button @click="trial"><FlaskConical :size="16"/>试算工资</button><div v-if="quote" class="quote-result"><p v-for="(p,i) in quote.parts" :key="i">{{p.label}}：{{p.quantity}}{{p.type==='PIECE'?'筐':'公斤'}} × {{p.rate}} 元 = {{p.amount}} 元</p><strong>本笔工资 ¥ {{Number(quote.amount).toFixed(2)}}</strong></div></section><p v-if="error" class="notice danger" role="alert">{{error}}</p><div class="modal-actions"><button @click="ruleProduct=null">取消</button><button class="primary" :disabled="busy" @click="publish"><Check :size="17"/>确认并发布规则</button></div>
  </section></div>
</template>
